function icon(string $name='arrow'):string{$paths=['arrow'=>'<path d="M5 12h14M13 6l6 6-6 6"/>','pin'=>'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>','sun'=>'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>','check'=>'<path d="m5 12 4 4L19 6"/>','clock'=>'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>','shield'=>'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>','menu'=>'<path d="M4 6h16M4 12h16M4 18h16"/>','spark'=>'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/>'];return '<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($paths[$name]??$paths['arrow']).'</svg>';}
function photo(array $p,string $class='',bool $priority=false):string{$src=safeImage($p['image']??'/assets/dubai.webp');$small=preg_replace('/\.webp$/','-small.webp',$src);$attrs='';$file=PUBLIC_ROOT.$small;if($small!==$src&&is_file($file))$attrs=' srcset="'.esc($small).' 720w, '.esc($src).' 1500w" sizes="'.($priority?'(max-width: 800px) 100vw, 1240px':'(max-width: 540px) 100vw, (max-width: 800px) 50vw, 420px').'"';return '<img class="'.esc($class).'" src="'.esc($src).'"'.$attrs.' alt="'.esc($p['imageAlt']??$p['title']??'UAE travel experience').'" width="1200" height="800" '.($priority?'fetchpriority="high" loading="eager"':'loading="lazy"').' decoding="async">';}
function card(array $t):string{ob_start();?><article class="tour-card reveal" data-tour-category="<?=esc($t['category'])?>"><a class="card-photo" href="<?=esc(pathFor($t))?>"><?=photo($t)?><span class="pill"><?=esc($t['category'])?></span><span class="circle-arrow"><?=icon()?></span></a><div class="card-body"><span class="meta"><?=icon('pin')?><?=esc(locationName($t['location']))?><?=!empty($t['duration'])?' <span>·</span> '.esc($t['duration']):''?></span><h3><a href="<?=esc(pathFor($t))?>"><?=esc($t['title'])?></a></h3><p><?=esc($t['summary'])?></p><div class="card-bottom"><div><?php if(price($t)>0):?><small>From <?=!empty($t['discountPrice'])?'<del>'.money($t['price']).'</del>':''?></small><strong><?=money(price($t))?></strong><small>/ <?=($t['pricingMode']??'per_person')==='per_person'?'person':(($t['pricingMode']??'')==='per_hour'?'hour':'vehicle')?></small><?php else:?><strong class="quote-price">Request a Quote</strong><small>Price confirmed for your dates</small><?php endif;?><small><?=esc($t['ticketOptions']??1)?> ticket option<?=($t['ticketOptions']??1)>1?'s':''?></small></div><a class="text-link" href="<?=esc(pathFor($t))?>">View tour <?=icon()?></a></div></div></article><?php return ob_get_clean();}
function cards(array $t,int $limit=999):string{return '<div class="tour-grid">'.implode('',array_map('card',array_slice($t,0,$limit))).'</div>';}
function renderPage(string $title,string $description,string $body,array $seo=[],bool $noindex=false,?array $record=null):void{$s=settings();$tracking=str_starts_with($GLOBALS['path']??'','/account')?normalizeTracking([]):trackingSettings();sessionOpen();$body.=referencePageExtras($GLOBALS['path']??'',$record);$systemMap=['/'=>'home','/tours'=>'tours-index','/guides'=>'guides-index','/contact'=>'contact'];if(isset($systemMap[$GLOBALS['path']??''])){$systemPage=getRecord('pages',$systemMap[$GLOBALS['path']]);if($systemPage){$seo=$systemPage['seo'];if(!empty($systemPage['content']))$body.='<section class="container prose section">'.$systemPage['content'].'</section>';}}$seo['title']=trim($seo['title']??'')?:$title;$seo['description']=trim($seo['description']??'')?:$description;$canonical=ORIGIN.($GLOBALS['path']??'/');$robots=STAGING||$noindex||!empty($seo['noindex'])?'noindex, nofollow':'index, follow';$image=ORIGIN.($record['image']??$s['heroImage']);header('Content-Type: text/html; charset=utf-8');header('Cache-Control: private, no-store, max-age=0');header('Vary: Cookie');if(STAGING)header('X-Robots-Tag: noindex, nofollow');?><!doctype html><html lang="en"><head><meta charset="utf-8"><?=trackingHead($tracking)?><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=esc($seo['title']??$title)?></title><meta name="description" content="<?=esc($seo['description']??$description)?>"><meta name="robots" content="<?=$robots?>"><link rel="canonical" href="<?=esc($canonical)?>"><?php if(!empty($seo['keywords'])):?><meta name="keywords" content="<?=esc($seo['keywords'])?>"><?php endif;?><meta property="og:type" content="<?=($record['kind']??'')==='posts'?'article':'website'?>"><meta property="og:title" content="<?=esc($seo['title']??$title)?>"><meta property="og:description" content="<?=esc($seo['description']??$description)?>"><meta property="og:url" content="<?=esc($canonical)?>"><meta property="og:image" content="<?=esc($image)?>"><meta name="twitter:card" content="summary_large_image"><meta name="theme-color" content="#0089ca"><link rel="icon" href="/assets/favicon.png" type="image/png"><link rel="preload" href="/assets/ibm-plex-regular.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/site.css?v=20261027live"><link rel="stylesheet" href="/assets/premium.css?v=20261027live"><script src="/assets/premium.js?v=20261027live" defer></script><script src="/assets/site.js?v=20261027live" defer></script><link rel="stylesheet" href="/assets/experience.css?v=20261027live"><link rel="stylesheet" href="/assets/reference.css?v=20261027gallery1"><script src="/assets/commerce.js?v=20261027live" defer></script><script type="application/ld+json"><?=json_encode(['@context'=>'https://schema.org','@type'=>'TravelAgency','name'=>$s['name'],'url'=>ORIGIN,'logo'=>ORIGIN.$s['logo'],'telephone'=>$s['phone'],'email'=>$s['email'],'address'=>['@type'=>'PostalAddress','streetAddress'=>$s['address'],'addressLocality'=>'Dubai','addressCountry'=>'AE']],JSON_UNESCAPED_SLASHES|JSON_HEX_TAG)?></script><?php if($record&&($record['kind']??'')==='posts'):?><script type="application/ld+json"><?=json_encode(['@context'=>'https://schema.org','@type'=>'BlogPosting','headline'=>$record['title'],'description'=>$record['summary'],'image'=>$image,'datePublished'=>$record['publishedAt'],'dateModified'=>$record['updatedAt'],'author'=>['@type'=>'Organization','name'=>$s['name']]],JSON_UNESCAPED_SLASHES|JSON_HEX_TAG)?></script><?php endif;?></head><body class="<?=($GLOBALS['path']??'')==='/'?'is-home':'is-inner'?>"><?=trackingBody($tracking)?><a class="skip" href="#main">Skip to content</a><div class="topbar"><div class="container"><span>UAE adventures. A new sky, a new life.</span><a href="tel:<?=esc(preg_replace('/[^+\d]/','',$s['phone']))?>"><?=esc($s['phone'])?></a><a href="mailto:<?=esc($s['email'])?>"><?=esc($s['email'])?></a></div></div><header class="header"><div class="container nav"><a class="brand" href="/" aria-label="Desert Sky Tourism home"><img src="<?=esc($s['logo'])?>" width="88" height="86" alt="Desert Sky Tourism — A new sky, a new life"><span class="brand-wordmark"><strong>DESERT SKY</strong><small>TOURISM</small></span></a><button class="menu-toggle" type="button" aria-label="Toggle navigation menu" aria-expanded="false" aria-controls="navigation"><?=icon('menu')?><span>Menu</span></button><nav id="navigation" aria-label="Main navigation"><a href="/"<?=($GLOBALS['path']??'')==='/'?' aria-current="page"':''?>>Home</a><details class="nav-dropdown"><summary>Destinations <span>⌄</span></summary><div><?php foreach(records('locations') as $l):?><a href="<?=esc(pathFor($l,'locations'))?>"><?=esc($l['title'])?><?=icon()?></a><?php endforeach;?><a href="/tours">All experiences <?=icon()?></a></div></details><details class="nav-dropdown"><summary>Experiences <span>⌄</span></summary><div><a href="/tours?destination=dubai&amp;category=City%20%26%20culture">Dubai city tours <?=icon()?></a><a href="/tours?destination=abu-dhabi&amp;category=City%20%26%20culture">Abu Dhabi city tours <?=icon()?></a><a href="/tours?category=Desert%20adventures">Desert safaris <?=icon()?></a><a href="/tours?category=On%20the%20water">Cruises &amp; yachts <?=icon()?></a><a href="/tours?category=Attractions%20%26%20days%20out">Attraction tickets <?=icon()?></a><a href="/tours">All experiences <?=icon()?></a></div></details><a href="/hotel-booking">Hotels</a><a href="/guides">Guides</a><a href="/contact">Contact</a></nav><div class="header-actions"><a class="header-cart" href="/cart" aria-label="Shopping cart"><?=commerceIcon('cart')?><span class="cart-count"><?=count($_SESSION['cart']??[])?></span></a><?php if($viewer=customer()):?><a class="header-signin" href="/account"><?=commerceIcon('user')?><span>My bookings</span></a><?php else:?><a class="header-signin" href="/account/sign-in">Sign in</a><a class="button nav-signup" href="/account/sign-up">Sign up</a><?php endif;?></div></div></header><main id="main"><?=$body?></main><?=referenceFooter()?><a class="whatsapp" href="https://wa.me/<?=esc(preg_replace('/\D/','',$s['whatsapp']?:$s['phone']))?>" aria-label="Chat with Desert Sky Tourism on WhatsApp" target="_blank" rel="noopener noreferrer"><svg width="25" height="25" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M21 11.5a9 9 0 0 1-13.4 7.8L3 21l1.7-4.6A9 9 0 1 1 21 11.5Z"/><path d="M8 7c-2 4 3 9 7 9l1-2-3-1-1 1-2-2 1-1-1-3Z"/></svg></a></body></html><?php }
function pageHeader(string $eyebrow,string $title,string $summary):string{$image='/assets/dubai.webp';$path=$GLOBALS['path']??'';if(str_contains($path,'abu-dhabi'))$image='/assets/abu-dhabi.webp';elseif(str_contains($path,'ras-al-khaimah'))$image='/assets/ras-al-khaimah.webp';elseif(in_array($path,['/guides','/about','/terms','/privacy']))$image='/assets/dubai-dunes-hero.webp';elseif($path==='/hotel-booking')$image='/assets/coast.webp';return '<section class="p-page-hero"><img src="'.esc($image).'" alt="UAE travel landscape" width="1800" height="1000" fetchpriority="high"><div class="container"><span class="eyebrow">'.esc($eyebrow).'</span><h1>'.esc($title).'</h1><p>'.esc($summary).'</p><div class="p-hero-breadcrumb"><a href="/">Home</a><span>/</span><span>'.esc($eyebrow).'</span></div></div></section>';}
function journalCards(int $limit=3):string{ob_start();?><div class="journal-grid"><?php foreach(array_slice(records('posts'),0,$limit) as $p):?><article class="journal-card reveal"><a href="<?=esc(pathFor($p,'posts'))?>"><?=photo($p)?></a><div><span class="eyebrow">Field notes · <?=date('d M Y',strtotime($p['publishedAt']))?></span><h3><a href="<?=esc(pathFor($p,'posts'))?>"><?=esc($p['title'])?></a></h3><p><?=esc($p['summary'])?></p><a class="text-link" href="<?=esc(pathFor($p,'posts'))?>">Read the story <?=icon()?></a></div></article><?php endforeach;?></div><?php return ob_get_clean();}
require_once __DIR__.'/premium.php';
require_once __DIR__.'/reference.php';
if($path==='/cart'||$path==='/account'||str_starts_with($path,'/account/')){require __DIR__.'/customer-pages.php';exit;}
if(str_starts_with($path,'/st_tour/')){header('Location: /tours/'.rawurlencode(substr($path,9)),true,301);exit;}if(str_starts_with($path,'/st_location/')){header('Location: /destinations/'.rawurlencode(substr($path,13)),true,301);exit;}if(in_array($path,['/about-us','/contact-us'])){header('Location: '.($path==='/about-us'?'/about':'/contact'),true,301);exit;}
if($path==='/robots.txt'){header('Content-Type: text/plain');echo STAGING?"User-agent: *\nDisallow: /\n":"User-agent: *\nDisallow: /dashboard\nDisallow: /api/\nDisallow: /booking\nDisallow: /thank-you\nDisallow: /cart\nDisallow: /account\nDisallow: /login\nSitemap: ".ORIGIN.'/sitemap.xml';exit;}
if($path==='/sitemap.xml'){header('Content-Type: application/xml; charset=utf-8');echo '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';$urls=[];foreach(['home'=>'/','tours-index'=>'/tours','guides-index'=>'/guides','contact'=>'/contact'] as $id=>$route){$p=getRecord('pages',$id);if($p&&empty($p['seo']['noindex']))$urls[]=['path'=>$route,'updatedAt'=>$p['updatedAt']??''];}foreach(['tours','posts','pages','locations'] as $kind)foreach(records($kind) as $p)if(empty($p['seo']['noindex'])&&empty($p['systemPath']))$urls[]=['path'=>pathFor($p,$kind),'updatedAt'=>$p['updatedAt']??$p['publishedAt']??''];foreach($urls as $u)echo '<url><loc>'.esc(ORIGIN.$u['path']).'</loc>'.(!empty($u['updatedAt'])?'<lastmod>'.esc(date('c',strtotime($u['updatedAt']))).'</lastmod>':'').'</url>';echo '</urlset>';exit;}
if($path==='/'){referenceHome();exit;}
if($path==='/tours'||str_starts_with($path,'/destinations/')){$loc=str_starts_with($path,'/destinations/')?findSlug('locations',substr($path,14)):null;if(str_starts_with($path,'/destinations/')&&!$loc)notFound();premiumListing($loc);exit;}
if(str_starts_with($path,'/tours/')){$slug=substr($path,7);$t=findSlug('tours',$slug);if(!$t){foreach(records('tours') as $x)if(in_array($slug,$x['oldSlugs']??[])){header('Location: '.pathFor($x),true,301);exit;}notFound();}premiumTour($t);exit;}
if($path==='/guides'){premiumJournal();exit;}
if(str_starts_with($path,'/guides/')){$slug=substr($path,8);$p=findSlug('posts',$slug);if(!$p){foreach(records('posts') as $x)if(in_array($slug,$x['oldSlugs']??[])){header('Location: '.pathFor($x,'posts'),true,301);exit;}notFound();}premiumArticle($p);exit;}
if($path==='/booking'){require __DIR__.'/booking.php';exit;}
if($path==='/thank-you'){require __DIR__.'/thank-you.php';exit;}
if($path==='/contact'){sessionOpen();$s=settings();ob_start();echo pageHeader('Let’s talk travel','Your next good day starts with hello.','A question, a custom trip or a special occasion? Tell us what you’re imagining.');?><section class="container p-contact-cards"><a href="tel:<?=esc(preg_replace('/[^+\d]/','',$s['phone']))?>"><span><?=premiumIcon('message')?></span><small>Let’s talk travel</small><strong><?=esc($s['phone'])?></strong><p>Call or chat about your plans.</p></a><a href="mailto:<?=esc($s['email'])?>"><span><?=premiumIcon('mail')?></span><small>Drop us a little hello</small><strong><?=esc($s['email'])?></strong><p>Share your questions and ideas.</p></a><a href="#contact-form"><span><?=icon('pin')?></span><small>Find your travel people</small><strong>Bur Dubai, Dubai</strong><p>Local knowledge, a personal connection.</p></a></section><section class="container section contact-layout"><div class="contact-details"><h2>Find us in Dubai.</h2><p><?=esc($s['address'])?></p><a href="tel:<?=esc(preg_replace('/[^+\d]/','',$s['phone']))?>"><?=esc($s['phone'])?></a><a href="tel:<?=esc(preg_replace('/[^+\d]/','',$s['phone2']))?>"><?=esc($s['phone2'])?></a><a href="tel:<?=esc(preg_replace('/[^+\d]/','',$s['landline']))?>"><?=esc($s['landline'])?></a><a href="mailto:<?=esc($s['email'])?>"><?=esc($s['email'])?></a><img src="/assets/coast.webp" width="700" height="600" loading="lazy" alt="Dubai cityscape by the water"></div><form id="contact-form" class="form-panel" data-csrf="<?=esc($_SESSION['csrf'])?>"><h2>Let’s make a plan.</h2><div class="form-grid"><label>Your name<input name="name" required autocomplete="name"></label><label>Email address<input name="email" type="email" required autocomplete="email"></label></div><label>Phone / WhatsApp<input name="phone" type="tel" autocomplete="tel"></label><label>What can we help with?<select name="subject"><option>Planning my UAE trip</option><option<?=($_GET['subject']??'')==='hotel'?' selected':''?>>Hotel booking enquiry</option><option>Private or group tour</option><option>Current tour price</option><option>Existing booking</option></select></label><label>Your message<textarea name="message" rows="6" required><?=isset($_GET['tour'])?'I’d like to know more about '.esc(str_replace('-',' ',text($_GET['tour']))).'.':''?></textarea></label><input class="honeypot" type="text" name="website" tabindex="-1" autocomplete="off" aria-hidden="true"><p class="muted">This is an enquiry, not a booking. We’ll contact you to discuss your plans.</p><button class="button" type="submit">Send my message <?=icon()?></button><div class="form-message" role="status"></div></form></section><?php renderPage('Contact Desert Sky Tourism | Dubai Tour Planning','Contact Desert Sky Tourism in Bur Dubai for UAE tours, private trips and hotel enquiries.',ob_get_clean());exit;}

$p=findSlug('pages',substr($path,1));if($p){premiumInfo($p);exit;}foreach(records('pages') as $p)if(in_array(substr($path,1),$p['oldSlugs']??[])){header('Location: '.pathFor($p,'pages'),true,301);exit;}notFound();
